\resumeSubHeadingListStart
\resumeSubheading
      {University of Maryland, College Park, United States \scriptsize{} }{CGPA: 3.67/4}
      {Master of Science in Applied Machine Learning}{August 2024 - May 2026}
\resumeSubHeadingListEnd
\section{Skills}
\begin{itemize}[leftmargin=0.15in, label={}]
\item \textbf{Languages:} \small{C++} \\
\textbf{Databases:} \small{Database operations, Testing and validating database operations} \\
\textbf{Tools:} \small{Debugging, Documentation of results, Testing/validation} \\
\textbf{Other:} \small{3D geometry, 3D software, Quality control (QC), QC/defects} \\
\end{itemize}
\section{Experience}
{\small
\resumeSubHeadingListStart

\resumeSubheading
  {Machine Learning Engineer Intern}{May 2025 -- August 2025}
  {Ayar Labs}{Santa Clara, CA}
  \resumeItemListStart
    \resumeItem{Designed and executed end-to-end C++/SQL test cases to validate database operations end-to-end for the 3D imaging software stack, ensuring correctness from persistence to geometry outputs across 25+ CRUD-to-geometry paths.}
    \resumeItem{Profiled and identified, reproduce, and document database-related defects with clear repro steps, documentation of results, and bug tracking artifacts to support quality control (QC) triage and resolution for 3D workflows.}
    \resumeItem{Investigated advanced 3D geometry problem-solving tasks by implementing C++ routines using CGAL and OpenCASCADE, verifying outputs against published benchmarks and replicating published results within 12\% across 8 benchmarks.}
  \resumeItemListEnd

\resumeSubheading
  {Software Engineer Intern}{July 2024 -- December 2024}
  {Indian Institute of Technology, Indore}{Indore, India}
  \resumeItemListStart
    \resumeItem{Contributed by partnering with the 3D software engineering team to integrate working C++ solutions through iterative code reviews, delivering 21 features across 4-week sprint cycles.}
    \resumeItem{Constructed by independently implementing and validating small-to-medium software components under senior guidance, using version control to build pipeline C++ changes that merged 11 validated components with passing CI checks.}
    \resumeItem{Collaborated by creating documentation and communicating results clearly, including test outcomes and 3D geometry solution behavior, producing Markdown + CI test reports that enabled consistent QC/defects triage across the team.}
  \resumeItemListEnd

\resumeSubheading
  {Software Engineer Intern}{January 2024 -- June 2024}
  {National Institute of Technology, Jaipur}{Jaipur, India}
  \resumeItemListStart
    \resumeItem{Developed Python-based test and validate database operations harnesses that reproduced edge-case failures, enabling faster defect isolation and reducing verification cycles from 5 days to 2 days during 3D software integration.}
    \resumeItem{Architected Python modules to run iterative QC cycles via CI test runs, reviewing defect reports, and confirming database and geometry fixes, reducing P1 incident response time from 63 minutes to 46 minutes.}
    \resumeItem{Implemented Python tooling to identify and assign defects in issue tracking by linking failing test assertions to structured defect reports, reprioritizing fixes to deliver incremental progress.}
  \resumeItemListEnd

\resumeSubheading
  {Software Engineer Intern}{May 2023 -- December 2023}
  {Indian Institute of Technology, Indore}{Indore, India}
  \resumeItemListStart
    \resumeItem{Prototyped C++ implementations for database operations and 3D geometry computations, then validated end-to-end performance by handling 9K concurrent connections with 12 ms average response time.}
    \resumeItem{Detected 58 previously untracked data gaps by assigning and tracking defects in bug tracking with sufficient detail, enabling reproducible issue reports and verification of resolution by the team.}
    \resumeItem{Partnered to create clear documentation and communicate results, including test outcomes and 3D geometry solution behavior, using Confluence and GitHub. Aligned 21 cross-functional stakeholders across 2 teams.}
  \resumeItemListEnd

\resumeSubHeadingListEnd

%-----------PROJECTS-----------
}
\section{Projects}
{\small
\resumeSubHeadingListStart
    \resumeSubheading
      {C++ End-to-End 3D Geometry QC Harness with Vector-Indexed Persistence Validation}{}
      {}{}
    \resumeItemListStart
      \resumeItem{\textbf{Tools used:} C++, PostgreSQL, pgTAP, GoogleTest, SQLite, CGAL}
      \resumeItem{Built a C++ QC harness that solved CGAL-based 3D geometry problems and validated end-to-end database persistence for imaging metadata.}
      \resumeItem{Detected 38 defect cases across Geometry-to-Storage workflows, improving QC coverage to 97\% while cutting repro time by 62\%.}
    \resumeItemListEnd
  \resumeSubHeadingListEnd

%-----------ACHIEVEMENTS-----------
}
\section{Achievements}
{\small
\begin{itemize}[leftmargin=0.15in, label={}]
    \item Published \emph{"CaDT-Net: Cascaded Deformable Transformer for Breast Cancer"} at ICONIP 2024, achieving 99\% accuracy in image classification.
    \item Solved 200+ LeetCode problems, focusing on Graphs, DP, and System Design.
\end{itemize}

%------------------------------------------
}
